// backend/tests/integration/hobby-gate.test.ts
// Testes de integração para Hobby Gate
// FASE 3: Hobby Gate

import { describe, it, expect, beforeAll, afterAll } from '@jest/globals';
import { v4 as uuidv4 } from 'uuid';
import { pool } from '../../src/core/database/pool';
import { categoryInputGateService } from '../../src/core/categories/category-input-gate.service';
import { hobbyVerbHeuristicService } from '../../src/core/categories/hobby-verb-heuristic.service';
import { hobbyMatcherService } from '../../src/core/categories/hobby-matcher.service';
import { hobbyRateLimitService } from '../../src/core/categories/hobby-rate-limit.service';
import { resolveGlobalUserId } from '../../src/core/identity/identity.utils';

describe('Hobby Gate - Integração', () => {
  const testTenantId = uuidv4();
  let testUserId: string;
  let testGlobalUserId: string;

  beforeAll(async () => {
    // Criar tenant de teste
    await pool.query(
      `INSERT INTO tenants (tenant_id, name, city_id)
       VALUES ($1, 'Test Tenant', NULL)
       ON CONFLICT (tenant_id) DO NOTHING`,
      [testTenantId]
    );

    // Criar usuário de teste
    testUserId = uuidv4();
    testGlobalUserId = uuidv4();

    await pool.query(
      `INSERT INTO global_users (global_user_id, full_name, created_at)
       VALUES ($1, 'Test User', now())
       ON CONFLICT (global_user_id) DO NOTHING`,
      [testGlobalUserId]
    );

    await pool.query(
      `INSERT INTO users (user_id, tenant_id, email, global_user_id, created_at)
       VALUES ($1, $2, 'test@test.com', $3, now())
       ON CONFLICT (user_id) DO NOTHING`,
      [testUserId, testTenantId, testGlobalUserId]
    );
  });

  afterAll(async () => {
    // Limpar dados de teste
    try {
      await pool.query(`DELETE FROM category_input_audit WHERE actor_id = $1`, [testUserId]);
      await pool.query(`DELETE FROM users WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM tenants WHERE tenant_id = $1`, [testTenantId]);
    } catch (error) {
      // Ignorar erros de limpeza
    }
  });

  describe('HobbyVerbHeuristicService', () => {
    describe('Bloqueio de verbos genéricos', () => {
      it('deve bloquear "ligar videogame"', () => {
        const result = hobbyVerbHeuristicService.validate('ligar videogame');
        expect(result.decision).toBe('DENY');
        expect(result.reasonCode).toBe('GENERIC_VERB_BLOCKED');
      });

      it('deve bloquear "mexer no celular"', () => {
        const result = hobbyVerbHeuristicService.validate('mexer no celular');
        expect(result.decision).toBe('DENY');
        expect(result.reasonCode).toBe('GENERIC_VERB_BLOCKED');
      });

      it('deve bloquear "ficar no computador"', () => {
        const result = hobbyVerbHeuristicService.validate('ficar no computador');
        expect(result.decision).toBe('DENY');
        expect(result.reasonCode).toBe('GENERIC_VERB_BLOCKED');
      });

      it('deve bloquear "abrir instagram"', () => {
        const result = hobbyVerbHeuristicService.validate('abrir instagram');
        expect(result.decision).toBe('DENY');
        expect(result.reasonCode).toBe('GENERIC_VERB_BLOCKED');
      });

      it('deve bloquear "jogando" (gerúndio genérico)', () => {
        const result = hobbyVerbHeuristicService.validate('jogando');
        expect(result.decision).toBe('DENY');
        expect(result.reasonCode).toBe('GENERIC_GERUND_BLOCKED');
      });
    });

    describe('Permissão de verbos válidos', () => {
      it('deve permitir "tocar violão" (será validado pelo matcher)', () => {
        const result = hobbyVerbHeuristicService.validate('tocar violão');
        expect(result.decision).toBe('ALLOW');
      });

      it('deve permitir "jogar xadrez" (será validado pelo matcher)', () => {
        const result = hobbyVerbHeuristicService.validate('jogar xadrez');
        expect(result.decision).toBe('ALLOW');
      });

      it('deve permitir "praticar ioga" (será validado pelo matcher)', () => {
        const result = hobbyVerbHeuristicService.validate('praticar ioga');
        expect(result.decision).toBe('ALLOW');
      });
    });
  });

  describe('HobbyMatcherService', () => {
    describe('Match exato', () => {
      it('deve encontrar match exato para "xadrez"', async () => {
        const result = await hobbyMatcherService.findMatch('xadrez');
        expect(result.matched).toBe(true);
        expect(result.reasonCode).toBe('EXACT_MATCH');
        expect(result.similarity).toBe(1.0);
      });

      it('deve encontrar match exato para "fotografia"', async () => {
        const result = await hobbyMatcherService.findMatch('fotografia');
        expect(result.matched).toBe(true);
        expect(result.reasonCode).toBe('EXACT_MATCH');
      });

      it('deve encontrar match exato para "tocar violão"', async () => {
        const result = await hobbyMatcherService.findMatch('tocar violão');
        expect(result.matched).toBe(true);
        expect(result.reasonCode).toBe('EXACT_MATCH');
      });
    });

    describe('Match fuzzy', () => {
      it('deve encontrar match fuzzy para "violao" → "tocar violão"', async () => {
        const result = await hobbyMatcherService.findMatch('violao');
        // Pode ser match exato ou fuzzy dependendo do dataset
        expect(result.matched).toBe(true);
      });

      it('deve encontrar match fuzzy para "fotografar" → "fotografia"', async () => {
        const result = await hobbyMatcherService.findMatch('fotografar');
        // Pode ser match exato ou fuzzy dependendo do dataset
        expect(result.matched).toBe(true);
      });
    });

    describe('Rejeição de hobbies inválidos', () => {
      it('deve rejeitar "ligar videogame"', async () => {
        const result = await hobbyMatcherService.findMatch('ligar videogame');
        expect(result.matched).toBe(false);
        expect(result.reasonCode).toBe('NOT_IN_HOBBY_DATASET');
      });

      it('deve rejeitar "mexer no celular"', async () => {
        const result = await hobbyMatcherService.findMatch('mexer no celular');
        expect(result.matched).toBe(false);
        expect(result.reasonCode).toBe('NOT_IN_HOBBY_DATASET');
      });
    });
  });

  describe('CategoryInputGateService - Contexto Hobby', () => {
    describe('ALLOW - Hobbies válidos', () => {
      it('deve permitir "xadrez"', async () => {
        const result = await categoryInputGateService.validate('xadrez', {
          context: 'hobby',
          tenantId: testTenantId,
          actorId: testUserId,
          globalUserId: testGlobalUserId,
        });
        expect(result.decision).toBe('ALLOW');
      });

      it('deve permitir "tocar violão"', async () => {
        const result = await categoryInputGateService.validate('tocar violão', {
          context: 'hobby',
          tenantId: testTenantId,
          actorId: testUserId,
          globalUserId: testGlobalUserId,
        });
        expect(result.decision).toBe('ALLOW');
      });

      it('deve permitir "fotografia"', async () => {
        const result = await categoryInputGateService.validate('fotografia', {
          context: 'hobby',
          tenantId: testTenantId,
          actorId: testUserId,
          globalUserId: testGlobalUserId,
        });
        expect(result.decision).toBe('ALLOW');
      });

      it('deve permitir "colecionar moedas"', async () => {
        const result = await categoryInputGateService.validate('colecionar moedas', {
          context: 'hobby',
          tenantId: testTenantId,
          actorId: testUserId,
          globalUserId: testGlobalUserId,
        });
        expect(result.decision).toBe('ALLOW');
      });
    });

    describe('DENY - Hobbies inválidos', () => {
      it('deve bloquear "ligar videogame"', async () => {
        const result = await categoryInputGateService.validate('ligar videogame', {
          context: 'hobby',
          tenantId: testTenantId,
          actorId: testUserId,
          globalUserId: testGlobalUserId,
        });
        expect(result.decision).toBe('DENY');
        expect(result.reasonCode).toBe('GENERIC_VERB_BLOCKED');
      });

      it('deve bloquear "mexer no celular"', async () => {
        const result = await categoryInputGateService.validate('mexer no celular', {
          context: 'hobby',
          tenantId: testTenantId,
          actorId: testUserId,
          globalUserId: testGlobalUserId,
        });
        expect(result.decision).toBe('DENY');
        expect(result.reasonCode).toBe('GENERIC_VERB_BLOCKED');
      });

      it('deve bloquear "ficar no computador"', async () => {
        const result = await categoryInputGateService.validate('ficar no computador', {
          context: 'hobby',
          tenantId: testTenantId,
          actorId: testUserId,
          globalUserId: testGlobalUserId,
        });
        expect(result.decision).toBe('DENY');
        expect(result.reasonCode).toBe('GENERIC_VERB_BLOCKED');
      });

      it('deve bloquear "abrir instagram"', async () => {
        const result = await categoryInputGateService.validate('abrir instagram', {
          context: 'hobby',
          tenantId: testTenantId,
          actorId: testUserId,
          globalUserId: testGlobalUserId,
        });
        expect(result.decision).toBe('DENY');
        expect(result.reasonCode).toBe('GENERIC_VERB_BLOCKED');
      });
    });

    describe('FUZZY - Hobbies com variações', () => {
      it('deve permitir "violao" com match fuzzy para "tocar violão"', async () => {
        const result = await categoryInputGateService.validate('violao', {
          context: 'hobby',
          tenantId: testTenantId,
          actorId: testUserId,
          globalUserId: testGlobalUserId,
        });
        // Pode ser ALLOW se encontrar match fuzzy ou DENY se não encontrar
        // O importante é que não seja bloqueado por verbo genérico
        expect(['ALLOW', 'DENY']).toContain(result.decision);
      });

      it('deve permitir "fotografar" com match fuzzy para "fotografia"', async () => {
        const result = await categoryInputGateService.validate('fotografar', {
          context: 'hobby',
          tenantId: testTenantId,
          actorId: testUserId,
          globalUserId: testGlobalUserId,
        });
        // Pode ser ALLOW se encontrar match fuzzy ou DENY se não encontrar
        expect(['ALLOW', 'DENY']).toContain(result.decision);
      });
    });
  });

  describe('HobbyRateLimitService', () => {
    it('deve permitir tentativas dentro do limite', async () => {
      const result = await hobbyRateLimitService.checkRateLimit(testUserId, testTenantId);
      expect(result.allowed).toBe(true);
      expect(result.remaining).toBeGreaterThanOrEqual(0);
    });

    it('deve verificar limite de hobbies por usuário', async () => {
      const result = await hobbyRateLimitService.checkHobbyLimit(testGlobalUserId);
      expect(result.allowed).toBe(true);
      expect(result.maxCount).toBe(30);
    });
  });
});




























